with ValidStores as (select * from stores where lower(store_name) like '%own%'), Agg as (select city, case when sqft >= 15687 then 'high' when sqft >= 6141 then 'mid' else 'low' end as sqft_bucket, avg(sqft) as avg_sqft from ValidStores group by city, case when sqft >= 15687 then 'high' when sqft >= 6141 then 'mid' else 'low' end) select city, avg_sqft from Agg where avg_sqft < 5700 order by avg_sqft
